// Category C: a code entered into separate cells (a one-time code, a PIN). There is no headless
// primitive, and the usual build (one input per cell, focus moved by hand) breaks paste, the
// platform's one-time-code autofill and how a screen reader reads the field. So this is ONE real
// input, React Aria's TextField, holding the whole code and spanning the row, with the cells drawn
// over it for the eye only (the shape shadcn's InputOTP takes). The input stays a text field to
// every reader; the cells are decoration that mirrors it.
import { FieldError, Input, Label, Text, TextField } from "react-aria-components";
import type { TextFieldProps, ValidationResult } from "react-aria-components";
import { useState, type Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./PinField.css";

type PinFieldSize = ControlSize;

export interface PinFieldProps
  extends Omit<TextFieldProps, "className" | "children" | "type" | "inputMode" | "maxLength" | "pattern"> {
  /**
   * Size axis: the cells and the field's text.
   *
   * @default "medium"
   */
  size?: PinFieldSize;
  /**
   * How many cells, the length of the code.
   *
   * @default 6
   */
  length?: number;
  /**
   * Accept digits only (a numeric keypad on a phone) or any letter or digit.
   *
   * @default "numeric"
   */
  characters?: "numeric" | "alphanumeric";
  /** Show a dot in each filled cell instead of the character, for a PIN. */
  isMasked?: boolean;
  /** Field label. */
  label?: string;
  /** Supporting description. */
  description?: string;
  /** Validation-failure message (shown in the isInvalid state). */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Additional class. sd-pin-field is always retained. */
  className?: string;
  /** Forwarded to the root DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function PinField({
  size = "medium",
  length = 6,
  characters = "numeric",
  isMasked = false,
  label,
  description,
  errorMessage,
  value,
  defaultValue,
  onChange,
  className,
  ref,
  ...props
}: PinFieldProps) {
  const allowed = characters === "numeric" ? /[^0-9]/g : /[^0-9a-z]/gi;
  // Every value is cleaned the same way, a supplied one included, so the cells and the submitted
  // value never disagree.
  const clean = (raw: string) => raw.replace(allowed, "").slice(0, length);
  const [own, setOwn] = useState(() => clean(defaultValue ?? ""));
  const [focused, setFocused] = useState(false);
  const code = clean(value ?? own);
  // The cell the next character lands in: after the last one typed, or the last cell once full.
  const active = Math.min(code.length, length - 1);

  return (
    <TextField
      {...props}
      ref={ref}
      value={code}
      // No `maxLength`: the browser would cut a pasted "12-34 56" to "12-34 " before the separators
      // are stripped, losing digits. The code is trimmed to `length` after cleaning instead.
      onChange={(next) => {
        const cleaned = clean(next);
        if (value === undefined) setOwn(cleaned);
        onChange?.(cleaned);
      }}
      inputMode={characters === "numeric" ? "numeric" : "text"}
      autoComplete={props.autoComplete ?? "one-time-code"}
      data-size={size}
      className={className ? `sd-pin-field ${className}` : "sd-pin-field"}
    >
      {({ isInvalid, isDisabled }) => (
        <>
          {label && (
            <Label data-disabled={isDisabled || undefined} className={`sd-pin-field__label sd-type-label-${roleSize(size)}`}>
              {label}
            </Label>
          )}
          <div className="sd-pin-field__cells" data-size={size}>
            <Input
              type={isMasked ? "password" : "text"}
              className={`sd-pin-field__input sd-type-body-${roleSize(size)}`}
              onFocus={() => setFocused(true)}
              onBlur={() => setFocused(false)}
              // The caret is invisible and the drawn cells cannot place it, so editing stays at the
              // end of the code (the highlighted cell), as one-time-code fields do: a caret moved
              // elsewhere is put back, unless the whole code is selected to be replaced.
              onSelect={(event) => {
                const input = event.currentTarget;
                const end = input.value.length;
                const whole = input.selectionStart === 0 && input.selectionEnd === end;
                if (!whole && (input.selectionStart !== end || input.selectionEnd !== end)) input.setSelectionRange(end, end);
              }}
            />
            {Array.from({ length }, (_, i) => (
              <div
                key={i}
                aria-hidden="true"
                data-size={size}
                data-filled={i < code.length || undefined}
                data-input-focused={(focused && i === active) || undefined}
                data-invalid={isInvalid || undefined}
                data-disabled={isDisabled || undefined}
                className={`sd-pin-field__cell sd-type-body-${roleSize(size)}`}
              >
                {i < code.length ? (isMasked ? "•" : code[i]) : null}
              </div>
            ))}
          </div>
          {description && (
            <Text slot="description" className={`sd-pin-field__description sd-type-caption-${roleSize(size)}`}>
              {description}
            </Text>
          )}
          <FieldError className={`sd-pin-field__error sd-type-caption-${roleSize(size)}`}>{errorMessage}</FieldError>
        </>
      )}
    </TextField>
  );
}

/* PinField.css — .sd-pin-field (+ __label · __cells · __input · __cell · __description · __error)
   One real input spans the row of cells and carries the code; it is transparent, so the cells drawn
   under it show the characters. The cell that will take the next character carries the field's
   focus treatment (contract § 6 rule 7: border-focus plus the ring), since that is where the caret
   would be. */
.sd-pin-field {
  display: flex;
  flex-direction: column;
  gap: var(--sd-pin-field-gap);
}
.sd-pin-field[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-pin-field__label {
  padding-inline: var(--sd-pin-field-text-padding-inline);
  color: var(--sd-pin-field-label-foreground);
}

.sd-pin-field__cells {
  --sd-pin-field-cell-radius-current: var(--sd-pin-field-cell-radius-medium);
  position: relative;
  display: inline-grid;
  grid-auto-flow: column;
  justify-content: start;
  gap: var(--sd-pin-field-cells-gap);
  --sd-pin-field-cell-size-current: var(--sd-pin-field-cell-size-medium);
}
.sd-pin-field__cells[data-size="x-small"] {
  --sd-pin-field-cell-radius-current: var(--sd-pin-field-cell-radius-x-small);
  --sd-pin-field-cell-size-current: var(--sd-pin-field-cell-size-x-small);
}
.sd-pin-field__cells[data-size="small"] {
  --sd-pin-field-cell-radius-current: var(--sd-pin-field-cell-radius-small);
  --sd-pin-field-cell-size-current: var(--sd-pin-field-cell-size-small);
}
.sd-pin-field__cells[data-size="large"] {
  --sd-pin-field-cell-radius-current: var(--sd-pin-field-cell-radius-large);
  --sd-pin-field-cell-size-current: var(--sd-pin-field-cell-size-large);
}
.sd-pin-field__cells[data-size="x-large"] {
  --sd-pin-field-cell-radius-current: var(--sd-pin-field-cell-radius-x-large);
  --sd-pin-field-cell-size-current: var(--sd-pin-field-cell-size-x-large);
}

/* Above the cells and clear: the pointer and the caret go to the one input wherever they land, and
   a pasted or autofilled code arrives whole. */
.sd-pin-field__input {
  position: absolute;
  inset: 0;
  z-index: 1;
  inline-size: 100%;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  color: transparent;
  caret-color: transparent;
  outline: none;
  cursor: text;
}
.sd-pin-field__input:disabled {
  cursor: not-allowed;
}

.sd-pin-field__cell {
  display: grid;
  place-items: center;
  inline-size: var(--sd-pin-field-cell-size-current);
  block-size: var(--sd-pin-field-cell-size-current);
  background: var(--sd-pin-field-cell-background);
  color: var(--sd-pin-field-cell-foreground);
  border: var(--sd-pin-field-cell-border-width) solid var(--sd-pin-field-cell-border);
  border-radius: var(--sd-pin-field-cell-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  font-variant-numeric: tabular-nums;
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-pin-field__cell[data-input-focused] {
  border-color: var(--sd-pin-field-cell-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-pin-field__cell[data-invalid] {
  border-color: var(--sd-pin-field-cell-border-invalid);
}
.sd-pin-field__cell[data-invalid][data-input-focused] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-pin-field-cell-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
}

.sd-pin-field__description {
  padding-inline: var(--sd-pin-field-text-padding-inline);
  color: var(--sd-pin-field-description-foreground);
}
.sd-pin-field__error {
  padding-inline: var(--sd-pin-field-text-padding-inline);
  color: var(--sd-pin-field-error-foreground);
}

@media (prefers-reduced-motion: reduce) {
  .sd-pin-field__cell {
    transition: none;
  }
}
